INSERT INTO chat_sdk_lists VALUES('msg-history:telegram:8641420749',777,'{"_type":"chat:Message","id":"8641420749:1746","threadId":"telegram:8641420749","text":", faut que tu comprennes une bonne fois pour toute que ce n''est pas impossible de rester en zone 2 en montant à plus de 4 %. À chaque fois que tu vois plus, c''est de la montée et si tu vois encore plus, c''est que c''est de la montée au-dessus de 11 %, comme il y avait aujourd''hui","formatted":{"type":"root","children":[{"type":"paragraph","children":[{"type":"text","value":", faut que tu comprennes une bonne fois pour toute que ce n''est pas impossible de rester en zone 2 en montant à plus de 4 %. À chaque fois que tu vois plus, c''est de la montée et si tu vois encore plus, c''est que c''est de la montée au-dessus de 11 %, comme il y avait aujourd''hui","position":{"start":{"line":1,"column":1,"offset":0},"end":{"line":1,"column":280,"offset":279}}}],"position":{"start":{"line":1,"column":1,"offset":0},"end":{"line":1,"column":280,"offset":279}}}],"position":{"start":{"line":1,"column":1,"offset":0},"end":{"line":1,"column":280,"offset":279}}},"raw":null,"author":{"userId":"8641420749","userName":"Clément","fullName":"Clément de Coligny","isBot":false,"isMe":false},"metadata":{"dateSent":"2026-09-14T17:27:43.000Z","edited":false},"attachments":[],"isMention":false}',1790011663500);
