INSERT INTO chat_sdk_lists VALUES('msg-history:telegram:-5124234082',779,'{"_type":"chat:Message","id":"-5124234082:3477","threadId":"telegram:-5124234082","text":"Supprime l''inventaire de fruits et légumes frais et je te redonne toute la liste avec tout ce qu''on vient acheter. Comme ça on est sûr que t''es à jour.\n- 10 pommes normales tres mures\n- 14 poires bio tres mures\n- 10 petites patates douces bio\n- 7 patates douces normales\n- 6 pommes de terre normales\n- 4 petites oignons bio\n- 2 oignons normaux\n- 2 têtes d''ail\n- 2 oignons rouges\n- 1 concombre\n- 2 carottes\n- 3 bananes bien mures\n- 2 citrons verts\n- 1 petit chou\n- 1 gros navet\n- 2 poivrons rouges\n- 1 poivron jaune\n- 1 poivron vert\n- 2 tomates\n- 250 g de tomates cerises\n- 300 g de figues\n J’ai peur de ne pas tout utiliser et de devoir jeter dans les jours qui viennent. J’ai une heure devant moi pour cuisiner. Quelle est la meilleure facon d’utiliser ce qu’on a pour avoir deja des choses pretes a l’avance ? Donne moi plusieurs options. Pas besoin de tout utiliser.","formatted":{"type":"root","children":[{"type":"paragraph","children":[{"type":"text","value":"Supprime l''inventaire de fruits et légumes frais et je te redonne toute la liste avec tout ce qu''on vient acheter. Comme ça on est sûr que t''es à jour.","position":{"start":{"line":1,"column":1,"offset":0},"end":{"line":1,"column":152,"offset":151}}}],"position":{"start":{"line":1,"column":1,"offset":0},"end":{"line":1,"column":152,"offset":151}}},{"type":"list","ordered":false,"start":null,"spread":false,"children":[{"type":"listItem","spread":false,"checked":null,"children":[{"type":"paragraph","children":[{"type":"text","value":"10 pommes normales tres mures","position":{"start":{"line":2,"column":3,"offset":154},"end":{"line":2,"column":32,"offset":183}}}],"position":{"start":{"line":2,"column":3,"offset":154},"end":{"line":2,"column":32,"offset":183}}}],"position":{"start":{"line":2,"column":1,"offset":152},"end":{"line":2,"