INSERT INTO chat_sdk_lists VALUES('msg-history:telegram:8641420749',815,'{"_type":"chat:Message","id":"8641420749:1844","threadId":"telegram:8641420749","text":"Dans mon plan de nutrition pour la course, je dois boire ou manger toutes les 20min. J’aime bien avoir un timer de 20min pour me le rappeler et aussi pour voir combien de temps il reste jusqu’au prochain intervalle de 20min. Mais je n’ai pas confiance en la drink alert de mon Garmin, parfois elle sonne pas, et je ne vois pas le temps qu’il reste. J’ai utilisé mon téléphone par le passé mais ça m’oblige à le sortir à chaque fois. \nDonc j’ai pensé à créer une session de 12h qui aurait ce format:\n- 20min Z1 échauffement\n- puis des intervalles de 20min Z2 avec un mini intervalle de 15sec de Z1 entre chaque pour boire/manger. Comme ça je sais que je dois boire à ce moment là et je peux voir combien de temps il reste. Qu’en penses tu ?","formatted":{"type":"root","children":[{"type":"paragraph","children":[{"type":"text","value":"Dans mon plan de nutrition pour la course, je dois boire ou manger toutes les 20min. J’aime bien avoir un timer de 20min pour me le rappeler et aussi pour voir combien de temps il reste jusqu’au prochain intervalle de 20min. Mais je n’ai pas confiance en la drink alert de mon Garmin, parfois elle sonne pas, et je ne vois pas le temps qu’il reste. J’ai utilisé mon téléphone par le passé mais ça m’oblige à le sortir à chaque fois.\nDonc j’ai pensé à créer une session de 12h qui aurait ce format:","position":{"start":{"line":1,"column":1,"offset":0},"end":{"line":2,"column":65,"offset":498}}}],"position":{"start":{"line":1,"column":1,"offset":0},"end":{"line":2,"column":65,"offset":498}}},{"type":"list","ordered":false,"start":null,"spread":false,"children":[{"type":"listItem","spread":false,"checked":null,"children":[{"type":"paragraph","children":[{"type":"text","value":"20min Z1 échauffement","position":{"start":{"line":3,"column":3,"offset":501},"end":{"line":3,"column":24,"offset":522}}}],"position":{"start":{"line":3,"column":3,"offset":501},"end":{"line":3,"column":24,"offset":522}}}],"position":{"start":{"line":3,"column":1,"offset":499},"end":{"line":3,"column":24,"offset":522}}},{"type":"listItem","spread":false,"checked":null,"children":[{"type":"paragraph","children":[{"type":"text","value":"puis des intervalles de 20min Z2 avec un mini intervalle de 15sec de Z1 entre chaque pour boire/manger. Comme ça je sais que je dois boire à ce moment là et je peux voir combien de temps il reste. Qu’en penses tu ?","position":{"start":{"line":4,"column":3,"offset":525},"end":{"line":4,"column":217,"offset":739}}}],"position":{"start":{"line":4,"column":3,"offset":525},"end":{"line":4,"column":217,"offset":739}}}],"position":{"start":{"line":4,"column":1,"offset":523},"end":{"line":4,"column":217,"offset":739}}}],"position":{"start":{"line":3,"column":1,"offset":499},"end":{"line":4,"column":217,"offset":739}}}],"position":{"start":{"line":1,"column":1,"offset":0},"end":{"line":4,"column":217,"offset":739}}},"raw":null,"author":{"userId":"8641420749","userName":"Clément","fullName":"Clément de Coligny","isBot":false,"isMe":false},"metadata":{"dateSent":"2026-09-22T08:42:27.000Z","edited":false},"attachments":[],"isMention":false}',1790671346575);
